// --- Brand-Daten (anpassen, identisch zu Sub: Send Offer WhatsApp) ---
const BRAND = {
  name: 'COMPANY_NAME',
  address: 'COMPANY_ADDRESS',
  tax_id: 'COMPANY_TAX_ID',
  logo_url: 'COMPANY_LOGO_URL',
  color: 'COMPANY_COLOR_HEX',
  email: 'COMPANY_CONTACT_EMAIL',
  phone: 'COMPANY_CONTACT_PHONE',
  website: 'COMPANY_WEBSITE'
};
const USt_PROZENT = 19;

const input = $input.first().json;
const positionen = input.positionen || [];
const verrechnungen = input.verrechnungen || [];

const eur = (n) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

let zwischensumme = 0;
const posRows = positionen.map((p, i) => {
  const summe = (Number(p.menge) || 0) * (Number(p.einzelpreis) || 0);
  zwischensumme += summe;
  return `<tr>
    <td>${i+1}</td>
    <td>${p.beschreibung}</td>
    <td style="text-align:right">${Number(p.menge).toLocaleString('de-DE')}</td>
    <td>${p.einheit}</td>
    <td style="text-align:right">${eur(p.einzelpreis)} EUR</td>
    <td style="text-align:right">${eur(summe)} EUR</td>
  </tr>`;
}).join('');

const verrRows = verrechnungen.map((v, i) => {
  const summe = (Number(v.stunden) || 0) * (Number(v.stundensatz) || 0);
  zwischensumme += summe;
  return `<tr>
    <td>V${i+1}</td>
    <td>${v.position}</td>
    <td style="text-align:right">${Number(v.stunden).toLocaleString('de-DE')}</td>
    <td>Std</td>
    <td style="text-align:right">${eur(v.stundensatz)} EUR</td>
    <td style="text-align:right">${eur(summe)} EUR</td>
  </tr>`;
}).join('');

const ust = zwischensumme * USt_PROZENT / 100;
const gesamt = zwischensumme + ust;

const html = `<!doctype html>
<html lang="de"><head>
<meta charset="utf-8" />
<title>Angebot ${input.angebotsnummer}</title>
<style>
  body { font-family: 'Helvetica', Arial, sans-serif; color: #222; padding: 32px; font-size: 11pt; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid ${BRAND.color}; padding-bottom: 16px; margin-bottom: 24px; }
  .header img { max-height: 60px; }
  .company { text-align: right; font-size: 9pt; color: #555; }
  h1 { color: ${BRAND.color}; margin: 0 0 8px 0; }
  .meta { display: flex; justify-content: space-between; margin: 16px 0; font-size: 10pt; }
  table.items { width: 100%; border-collapse: collapse; margin-top: 16px; }
  table.items th { background: ${BRAND.color}; color: #fff; text-align: left; padding: 8px; font-size: 10pt; }
  table.items td { border-bottom: 1px solid #eee; padding: 8px; vertical-align: top; }
  table.items tr:nth-child(even) td { background: #f8f8f8; }
  .totals { width: 320px; margin-left: auto; margin-top: 16px; font-size: 11pt; }
  .totals .row { display: flex; justify-content: space-between; padding: 4px 0; }
  .totals .row.total { border-top: 2px solid ${BRAND.color}; font-weight: bold; font-size: 13pt; padding-top: 8px; margin-top: 8px; }
  .footer { margin-top: 48px; font-size: 9pt; color: #555; border-top: 1px solid #ddd; padding-top: 12px; }
</style></head><body>
  <div class="header">
    <div><img src="${BRAND.logo_url}" alt="Logo" /></div>
    <div class="company">
      <strong>${BRAND.name}</strong><br>
      ${BRAND.address}<br>
      USt-IdNr.: ${BRAND.tax_id}<br>
      ${BRAND.email} &middot; ${BRAND.phone}
    </div>
  </div>
  <h1>Angebot ${input.angebotsnummer}</h1>
  <div class="meta">
    <div><strong>Kunde:</strong> ${input.kunde_name}</div>
    <div><strong>Datum:</strong> ${input.datum} &nbsp; <strong>Gueltig bis:</strong> ${input.gueltig_bis}</div>
  </div>
  <table class="items">
    <thead><tr><th>Pos</th><th>Beschreibung</th><th>Menge</th><th>Einheit</th><th>Einzelpreis</th><th>Summe</th></tr></thead>
    <tbody>${posRows}${verrRows}</tbody>
  </table>
  <div class="totals">
    <div class="row"><span>Zwischensumme</span><span>${eur(zwischensumme)} EUR</span></div>
    <div class="row"><span>USt ${USt_PROZENT}%</span><span>${eur(ust)} EUR</span></div>
    <div class="row total"><span>Gesamtsumme</span><span>${eur(gesamt)} EUR</span></div>
  </div>
  <div class="footer">
    Zahlungsbedingungen: 14 Tage netto. Es gelten unsere AGB. Dieses Angebot ist gueltig bis ${input.gueltig_bis}.<br>
    ${BRAND.name} &middot; ${BRAND.website}
  </div>
</body></html>`;

const mailHtml = `<p>Lieber Kunde,</p>
<p>hier ist Ihr Angebot <strong>${input.angebotsnummer}</strong> vom ${input.datum}, gueltig bis ${input.gueltig_bis}.</p>
<p>Bei Fragen oder zur Auftragserteilung antworten Sie einfach auf diese Mail oder rufen uns an.</p>
<p>Freundliche Gruesse<br>Ihr Team von ${BRAND.name}</p>`;

return [{ json: {
  html,
  mailHtml,
  angebotsnummer: input.angebotsnummer,
  filename: `Angebot_${input.angebotsnummer}.pdf`,
  kunde_name: input.kunde_name,
  kunde_email: input.kunde_email,
  betreff: `Angebot ${input.angebotsnummer} - ${BRAND.name}`
} }];
